package com.bank.index;

import java.util.*;
import java.util.concurrent.ConcurrentMap;
import java.util.logging.*;

public class ConcurrentMapDemo {
    private static final Logger log = Logger.getLogger("Index");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(101, "Rajesh"), new Employee(102, "Priya"), new Employee(103, "Amit"));
        IndexService service = new IndexService();

        ConcurrentMap<Integer, String> index = service.concurrentIndex(staff);
        log.info(() -> "concurrent index type=" + index.getClass().getSimpleName()
            + " 102=" + index.get(102));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final int id;
    private final String name;
        Employee(int id, String name) { this.id = id;
        this.name = name; }
    int getId() { return id; }
    String getName() { return name; }
}

// ─── Would be in service/IndexService.java ───
class IndexService {
    ConcurrentMap<Integer, String> concurrentIndex(List<Employee> staff) {
        return staff.parallelStream()                                  // parallel source
            .collect(java.util.stream.Collectors.toConcurrentMap(
                Employee::getId,       // key
                Employee::getName,     // value
                (a, b) -> a));         // merge (safety on duplicate keys)
    }
}
